def build_injuries():
    """Retourne 205+ protocoles complets de prévention, préhab, rééducation & mobilité."""
    entries = []
    seen = set()

    for title, subcat, summary, protocol, red_flags, kw in INJURIES_PART_A:
        key = title.strip().lower()
        if key in seen:
            continue
        seen.add(key)
        body = (
            f"SYNTHÈSE CLINIQUE :\n{summary}\n\n"
            f"PROTOCOLE & CONDUITE PRATIQUE :\n{protocol}\n\n"
            f"DRAPEAUX ROUGES (CONSULTER MÉDECIN / URGENCES) :\n{red_flags}\n\n"
            f"Note : Information éducative de sciences du sport — ne remplace pas un diagnostic médical ou kinésithérapique."
        )
        meta = {"zone": subcat, "drapeaux_rouges": red_flags, "mots_cles": kw}
        entries.append({
            "category": "blessures",
            "subcategory": subcat,
            "title": title,
            "summary": f"{subcat} — {summary}",
            "body": body,
            "tags": f"blessures,reeducation,prehab,{subcat.lower()},{kw}",
            "metadata_json": json.dumps(meta, ensure_ascii=False),
        })

    for title, subcat, summary, protocol, kw in INJURIES_PART_B + EXTRA_INJURIES_CATALOG:
        key = title.strip().lower()
        if key in seen:
            continue
        seen.add(key)
        body = (
            f"CONTEXTE :\n{summary}\n\n"
            f"PROTOCOLE RECOMMANDÉ :\n{protocol}\n\n"
            f"PRÉCAUTION : En cas de douleur vive aiguë, gonflement, blocage, engourdissement ou absence d'amélioration sous 10-14 jours, consultez un médecin du sport ou kinésithérapeute."
        )
        meta = {"zone": subcat, "mots_cles": kw}
        entries.append({
            "category": "blessures",
            "subcategory": subcat,
            "title": title,
            "summary": f"{subcat} — {summary}",
            "body": body,
            "tags": f"blessures,prevention,prehab,mobilite,{subcat.lower()},{kw}",
            "metadata_json": json.dumps(meta, ensure_ascii=False),
        })

    return entries


if __name__ == "__main__":
    inj = build_injuries()
    print(f"Total injuries/rehab/mobility entries: {len(inj)}")
